"""Cria uma edição visual independente a partir do snapshot do dashboard original.

Uso: python 08_gerar_dashboard_observatory.py
Não modifica o dashboard original nem refaz a coleta de mercado.
"""
from pathlib import Path
import json
import re

ROOT = Path(__file__).resolve().parent
source = (ROOT / "output/dashboard.html").read_text(encoding="utf-8")
data = json.loads(re.search(r'<script id="dashboard-data" type="application/json">(.*?)</script>', source, re.S).group(1))

